-- Additive identity and authority. Legacy sessions remain until explicit invalidation.
CREATE TABLE authority_principals (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('human','agent','connector','system')), human_id TEXT, state TEXT NOT NULL CHECK(state IN ('invited','active','removed','erased')), authentication_epoch INTEGER NOT NULL DEFAULT 1, initial_owner INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1);
INSERT INTO authority_principals(id,kind,human_id,state,created_at,updated_at) SELECT id,'human',id,CASE WHEN active=1 THEN 'active' ELSE 'removed' END,created_at,updated_at FROM operators;
CREATE TABLE authority_sessions (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, authentication_epoch INTEGER NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE authority_magic_tokens (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), nonce_hash TEXT NOT NULL UNIQUE, return_to TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER, receipt_id TEXT, delivery_state TEXT);
CREATE TABLE authority_rate_limits (key_hash TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE authority_credentials (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), token_hash TEXT NOT NULL UNIQUE, audience TEXT NOT NULL, scopes_json TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE authority_policies (id TEXT PRIMARY KEY, app_id TEXT NOT NULL, name TEXT NOT NULL, rules_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE authority_memberships (principal_id TEXT NOT NULL REFERENCES authority_principals(id), app_id TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES authority_policies(id), legacy INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(principal_id,app_id));
CREATE TABLE authority_grants (id TEXT PRIMARY KEY, issuer_id TEXT NOT NULL REFERENCES authority_principals(id), delegate_id TEXT NOT NULL REFERENCES authority_principals(id), app_id TEXT NOT NULL, spec_json TEXT NOT NULL, impact_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('proposed','active','revoked','expired')), version INTEGER NOT NULL DEFAULT 1, starts_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE authority_budgets (grant_id TEXT NOT NULL REFERENCES authority_grants(id), unit TEXT NOT NULL, ceiling TEXT NOT NULL, consumed TEXT NOT NULL DEFAULT '0', reserved TEXT NOT NULL DEFAULT '0', version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(grant_id,unit));
CREATE TABLE authority_reservations (id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES authority_grants(id), grant_version INTEGER NOT NULL, command_id TEXT NOT NULL, unit TEXT NOT NULL, amount TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved','consumed','released')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(command_id,grant_id,unit));
CREATE INDEX authority_sessions_principal ON authority_sessions(principal_id);
CREATE INDEX authority_grants_delegate ON authority_grants(delegate_id,app_id,state);
CREATE INDEX authority_magic_expiry ON authority_magic_tokens(expires_at);
-- Plaintext legacy credentials cannot be safely retained. Preserve session history, revoke secrets.
UPDATE sessions SET revoked_at=COALESCE(revoked_at,unixepoch()*1000), token='retired:'||id;
